mapper.select:
SELECT count(*)
  FROM flt16_except_person
 WHERE flt16_company_id        = #{companyId}
   AND flt16_person_id         = #{personId}
   AND flt16_except_person_id != #{exceptPersonId}

mapper.update:
UPDATE flt16_except_person
   SET flt16_person_id      = #{req.personId},
       flt16_rpt_start_date = CAST(#{req.rptStartDate,jdbcType=VARCHAR} AS date),
       flt16_reason         = #{req.reason,jdbcType=VARCHAR}
 WHERE flt16_except_person_id = #{req.exceptPersonId}
   AND flt16_company_id       = #{companyId}

mapper.delete:
DELETE FROM flt16_except_person
 WHERE flt16_company_id = #{companyId}
   AND flt16_except_person_id IN
#{exceptPersonId}
